import { Link } from 'react-router-dom'
import { ChevronDown, Search } from 'lucide-react'

export default function Header() {
  return (
    <header className="bg-white shadow-md">
      <div className="container mx-auto px-4 py-4 flex items-center justify-between">
        {/* Left Section: Logo */}
        <div className="flex items-center space-x-6">
          <Link to="/">
            <img src="/k1.jpeg" alt="Dubizzle Logo" className="w-[120px] h-auto" />
          </Link>
          {/* Dropdown for Location */}
          <div className="flex items-center space-x-2">
            <span className="text-red-600">
              <svg
                xmlns="http://www.w3.org/2000/svg"
                className="w-5 h-5"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M12 11c0 1.657-1.343 3-3 3s-3-1.343-3-3 1.343-3 3-3 3 1.343 3 3zM12 11v3m6-6a9 9 0 11-6-6c1.488-.276 2.815.374 3.514 1.47M6.343 6.343l1.414 1.414M15.88 15.88a3 3 0 004.243 0 3 3 0 00.273-4.01m0 0l-1.414-1.414M18 18v3m0 0h-3m3 0a9 9 0 11-9-9m6-6v3"
                />
              </svg>
            </span>
            <button className="flex items-center text-gray-600 hover:text-gray-800">
              Egypt <ChevronDown size={16} />
            </button>
          </div>
        </div>

        {/* Middle Section: Search Bar */}
        <div className="flex-grow mx-6">
          <div className="flex items-center bg-gray-100 rounded-md">
            <input
              type="text"
              placeholder="Find Cars, Mobile Phones and more..."
              className="flex-grow p-2 bg-transparent focus:outline-none"
            />
            <button className="p-2 bg-red-500 text-white rounded-r-md">
              <Search size={24} />
            </button>
          </div>
        </div>

        {/* Right Section: Options */}
        <div className="flex items-center space-x-6">
          <button className="text-gray-600 hover:text-gray-800">العربية</button>
          <button className="text-gray-600 hover:text-gray-800 underline">Login</button>
          <button className="bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700">
            Sell
          </button>
        </div>
      </div>

      {/* Categories (Optional) */}
      <div className="container mx-auto px-4 py-2 border-t border-gray-200">
        <div className="flex space-x-4 text-gray-600">
          <button className="hover:text-gray-800">Vehicles</button>
          <button className="hover:text-gray-800">Properties</button>
          <button className="hover:text-gray-800">Mobiles & Tablets</button>
          <button className="hover:text-gray-800">Jobs</button>
          <button className="hover:text-gray-800">Electronics & Appliances</button>
          <button className="hover:text-gray-800">Furniture & Decor</button>
          <button className="hover:text-gray-800">More Categories</button>
        </div>
      </div>
    </header>
  )
}
